import { Self } from './definition';
import { Invocation } from '../interface';
import { resolveCodeByReference, resolveCrmCustomerByReference } from '../../scripts/helper';
import { IContext } from '../../scripts/data_types';
import { timeShift } from '../../scripts/timeshift';
import { ProjectSocialMediaPost } from '../../scripts/data_types_project';
import { ProcessorTypes } from '@eip/core';

export function process(invocation: Invocation, self: Self) {
  const mutations = [];
  const context: IContext = invocation.processors.createSocialMediaPost.input.context;
  const socialMediaPost: ProjectSocialMediaPost = invocation.processors.createSocialMediaPost.input.socialMediaPost;

  // task
  mutations.push(handleSocialMediaPost(context, socialMediaPost));

  if (mutations.filter(Boolean).length > 0) {
      self.withOutlet('hasMutations');
  }
  else {
    self.withOutlet('noMutations');
  }
  return mutations.filter(Boolean);
}

function handleSocialMediaPost(context: IContext, socialMediaPost: ProjectSocialMediaPost) {
  return ProcessorTypes.dataMutation.createModifyEntityMutation({mutationDatas: [
    Object.assign(
      {
        entityId: 'Y-SocialMediaPost', 
        operation: 'CREATE',
      },
      createProjectSocialMediaPostMutationAttributes(context, socialMediaPost)
    )
  ]});
}

function createProjectSocialMediaPostMutationAttributes(context: IContext, socialMediaPost: ProjectSocialMediaPost) {
  return {
    'y-channel': socialMediaPost['y-channel'],
    'y-comments': socialMediaPost['y-comments'],
    'y-customer': resolveCrmCustomerByReference(context, socialMediaPost['y-customer']?.globalKey),
    'y-message': socialMediaPost['y-message'],
    'y-platform': resolveCodeByReference(context, 'SocialMediaPlatform', socialMediaPost['y-platform']),
    'y-postedOn': timeShift(context, socialMediaPost['y-postedOn']),
    'y-reactions': socialMediaPost['y-reactions'],
    'y-sentiments': resolveCodeByReference(context, 'SocialMediaSentiment', socialMediaPost['y-sentiments']),
    'y-shares': socialMediaPost['y-shares']
  };
}

